import React from 'react';
import { Link } from 'react-router-dom';

const Navbar = ({ isAuthenticated, setAuth }) => {
  const handleLogout = () => {
    localStorage.removeItem('token');
    setAuth(false);
  };

  return (
    <nav>
      <div className="nav-wrapper">
        <Link to="/" className="nav-brand">
          MyApp
        </Link>
        <div className="nav-links">
          {isAuthenticated ? (
            <>
              <Link to="/dashboard" className="nav-link">
                Dashboard
              </Link>
              <button onClick={handleLogout} className="nav-link btn-danger" style={{ padding: '0.5rem 1rem', cursor: 'pointer' }}>
                Logout
              </button>
            </>
          ) : (
            <>
              <Link to="/login" className="nav-link">
                Sign In
              </Link>
              <Link to="/register" className="nav-link btn-success" style={{ padding: '0.5rem 1rem' }}>
                Sign Up
              </Link>
            </>
          )}
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
